local ServiceScope = require(script.Parent.ServiceScope)

local ServiceProvider = {}
ServiceProvider.__index = ServiceProvider

function ServiceProvider.new(parent, serviceCollection, luaTypeProvider)
	local ServiceResolverManager = require(script.Parent.ServiceResolverManager)
	local self = setmetatable({}, ServiceProvider)
	self._luaTypeProvider = luaTypeProvider
	self.Parent = parent
	self._scopes = {}
	self._serviceResolverManager = ServiceResolverManager.new(serviceCollection, self._luaTypeProvider)
	self.IsRoot = parent == nil
	self.Services = serviceCollection
	self._createdObjectHistory = {}
	self._createdObjectHistoryCache = {}
	self._newCache = {}
	self._newCacheCount = 0
	self.DisposeCalled = false
	self._disposed = {}
	return self
end

function ServiceProvider:GetService(service: string)
	if self.DisposeCalled then
		error("ObjectDisposedException")
	end

	local result = self:GetServiceWithUnsolved(nil, service)

	if self.DisposeCalled then
		error("ObjectDisposedException")
	end

	return result
end

function ServiceProvider:GetRequiredService(service: string)
	local result = self:GetService(service)
	if not result then
		warn(debug.traceback())
		error("Service not found: " .. service)
	end
	return result
end

function ServiceProvider:GetServiceWithUnsolved(unsolved, serviceType)
	if serviceType == "IServiceProvider" then
		return self
	end
	return self._serviceResolverManager:Resolve(self, serviceType, unsolved, nil)
end

function ServiceProvider:CreateScope(): IServiceScope
	local scopeProvider = ServiceProvider.new(self, self.Services, self._luaTypeProvider)
	local scope = ServiceScope.new(scopeProvider)
	self._scopes[scope] = true
	return scope
end

function ServiceProvider:Dispose()
	if self.DisposeCalled then
		return
	end
	self.DisposeCalled = true

	-- 1. 先销毁所有创建的对象
	for i = #self._createdObjectHistory, 1, -1 do
		local s = self._createdObjectHistory[i]
		if not s.descriptor.ImplementationInstance then
			if type(s.object) == "table" and type(s.object.Dispose) == "function" then
				if not self._disposed[s.object] then
					self._disposed[s.object] = true
					s.object:Dispose()
				end
			end
		end
	end

	self._newCache = {}
	self._createdObjectHistory = {}

	local scopesToDispose = {}
	for scope, _ in pairs(self._scopes) do
		if type(scope) == "table" then
			table.insert(scopesToDispose, scope)
		end
	end
	self._scopes = {}

	for _, scope in ipairs(scopesToDispose) do
		if not scope._disposed then
			scope:Dispose()
		end
	end
end

function ServiceProvider:TryGetCachedService(descriptor, service)
	local o = self._newCache[descriptor]
	local cached = o ~= nil

	if descriptor.ServiceType.IsGenericTypeDefinition then
		if cached then
			local dict = o
			o = dict[service]
			cached = o ~= nil
		end
		return cached, o
	else
		return cached, o
	end
end

function ServiceProvider:AddCache(descriptor, service, o)
	local cached = self._newCache[descriptor]
	if not cached then
		self._newCacheCount += 1
	end

	if descriptor.ServiceType.IsGenericTypeDefinition then
		local dict = self._newCache[descriptor]
		if not dict then
			dict = {}
			self._newCache[descriptor] = dict
		end
		dict[service] = o
	else
		self._newCache[descriptor] = o
	end
end

function ServiceProvider:AddCreatedObjectHistory(descriptor, o)
	local dCache = self._createdObjectHistoryCache[descriptor]
	if not dCache then
		dCache = {}
		self._createdObjectHistoryCache[descriptor] = dCache
	end

	local oCache = dCache[o]
	if not oCache then
		dCache[o] = true
		table.insert(self._createdObjectHistory, { descriptor = descriptor, object = o })
	end
end

return ServiceProvider
